function expressionScore(a={}){
 const fail=m=>{throw Object.assign(Error(m),{status:400})};
 if(!a||!['speech','dance','sing'].includes(a.mode))fail('Elegí habla, baile o canto sintético.');
 const tempo=a.tempo??100;if(!Number.isInteger(tempo)||tempo<60||tempo>140)fail('El tempo debe estar entre 60 y 140.');
 if(a.text!=null&&(typeof a.text!=='string'||a.text.length>400))fail('Usá un texto de hasta 400 caracteres.');
 const text=(a.text||'¡Hola, Rick! Estoy listo para ayudarte.').trim();if(!text)fail('Escribí un texto para el agente.');
 const beat=60000/tempo,notes=a.mode==='sing'?[60,64,67,64,65,62,60,60].map((midi,i)=>({midi,start_ms:Math.round(i*beat),duration_ms:Math.round(beat*.82),syllable:['la','le','li','lo','lu','la','la','la'][i]})):[];
 return {version:1,mode:a.mode,text:a.mode==='speech'?text:null,lang:'es-SV',tempo,duration_ms:a.mode==='speech'?null:Math.round(beat*8),notes,motion:a.mode==='dance'||a.mode==='sing'?[{transform:'translateY(0) rotate(0deg)'},{transform:'translateY(-9px) rotate(-8deg)'},{transform:'translateY(0) rotate(8deg)'},{transform:'translateY(-5px) rotate(-5deg)'},{transform:'translateY(0) rotate(0deg)'}]:[],caption:a.mode==='sing'?'La le li lo lu la la la · melodía vocal sintética original':a.mode==='dance'?'Baile original del avatar, sin sonido':text,scope:a.mode==='sing'?'Sílabas sintetizadas; voz cantada natural y letras completas pendientes.':a.mode==='speech'?'Voces del dispositivo; disponibilidad y acento dependen del navegador.':'Animación web; respeta movimiento reducido.',execution:'prepared_only',requires_active_browser:true,original_sequence:true};
}

