const row=(key,label,basis)=>({key,label,basis});
function registrationChecklist(data){
 const list=[row('application','Solicitud y datos del producto','Formulario vigente de SRS'),row('representation','Representación y profesional responsable','Poderes y nombramientos; validar inscripción y formalidades')];
 if(data.procedure==='new'&&data.product_type==='chemical')list.push(
  row('certification','Certificación farmacéutica y BPM aplicables','RTCA 7.3: CPF y alternativa CVL/BPM; confirmar cobertura y formalidades'),
  row('formula','Fórmula cualitativa y cuantitativa','RTCA 7.5'),row('monograph','Monografía y referencias','RTCA 7.6'),row('analysis','Métodos y validación analítica','RTCA 7.7'),row('specifications','Especificaciones del producto terminado','RTCA 7.8'),row('labels','Etiquetas, empaque e inserto','RTCA 7.9'),row('stability','Informe de estabilidad','RTCA 7.10'),row('clinical_basis','Respaldo de seguridad/eficacia, según corresponda','RTCA 7.11; aplicabilidad por revisión profesional'));
 if(data.procedure==='new'&&data.product_type==='biological')list.push(row('ctd_1','CTD 1 · administrativo','RTS 11.02.05:25; confirmar vigencia al expediente'),row('ctd_2','CTD 2 · resúmenes','Revisión especializada'),row('ctd_3','CTD 3 · calidad','Revisión especializada'),row('ctd_4','CTD 4 · no clínico','Revisión especializada'),row('ctd_5','CTD 5 · clínico','Revisión especializada'));
 if(data.procedure==='recognition')list.push(row('reference_registration','Registro de referencia y elegibilidad de reconocimiento','Confirmar modalidad y requisitos vigentes de la SRS; no basta una aprobación extranjera'));
 if(data.procedure==='renewal')list.push(row('current_registration','Registro vigente y antecedentes de renovación','Confirmar requisitos actuales y periodo aplicable'));
 if(data.procedure==='change')list.push(row('change_description','Cambio solicitado y expediente vigente','Identificar tipo y soporte específico; no reutilizar checklist de primer registro'));
 if(data.manufacturing_contract===true)list.push(row('manufacturing_contract','Contrato de fabricación aplicable','RTCA 7.4; confirmar formalidades y posibles excepciones'));
 list.push(row('local_requirements','Validación de requisitos locales y condicionales','Guía SRS vigente: confirmar arancel, muestras/patrones, bioequivalencia, formalidades y excepciones según caso'));
 return list;
}
function planSVRegistration(data={}){
 const fail=m=>{throw Object.assign(Error(m),{status:400})};
 if(!data||typeof data!=='object'||Array.isArray(data)||typeof data.product_name!=='string'||data.product_name.length>150||!['chemical','biological','natural','unknown'].includes(data.product_type)||!['national','foreign','unknown'].includes(data.origin)||!['new','renewal','change','recognition','unknown'].includes(data.procedure)||![true,false,null].includes(data.manufacturing_contract)||!Array.isArray(data.documents)||data.documents.length>30)fail('Revisá la ficha del producto y el tipo de trámite.');
 const identityFields={ingredient:'Principio activo',strength:'Concentración',dosage_form:'Forma farmacéutica',holder:'Titular',manufacturer:'Fabricante y sitios',manufacturing_country:'País de fabricación'};for(const key of Object.keys(identityFields))if(data[key]!=null&&(typeof data[key]!=='string'||data[key].length>200))fail('Revisá '+identityFields[key]);
 const seen=new Set();for(const d of data.documents){if(!d||typeof d.key!=='string'||d.key.length>60||seen.has(d.key)||!['missing','available','reviewed','not_applicable'].includes(d.status)||typeof d.reference!=='string'||d.reference.length>300||typeof d.justification!=='string'||d.justification.length>500||(['available','reviewed'].includes(d.status)&&!d.reference.trim())||(d.status==='not_applicable'&&!d.justification.trim()))fail('Cada documento necesita un estado y su referencia o justificación cuando corresponda.');seen.add(d.key);}
 const questions=Object.entries(identityFields).filter(([key])=>!data[key]?.trim()).map(([,label])=>label+'.');if(!data.product_name.trim())questions.push('Nombre del producto, principio activo, concentración y forma farmacéutica.');if(data.product_type==='unknown')questions.push('Clasificación del producto.');if(data.origin==='unknown')questions.push('Fabricación nacional o extranjera y fabricantes involucrados.');if(data.procedure==='unknown')questions.push('Primera inscripción, renovación, cambio o reconocimiento.');if(data.manufacturing_contract===null)questions.push('¿Existe fabricación por terceros?');if(data.product_type==='natural')questions.push('Aplicar normativa específica de productos naturales; checklist especializado pendiente.');
 const checklist=registrationChecklist(data).map((r,i)=>{const d=data.documents.find(d=>d.key===r.key);return {...r,index:String(i+1).padStart(2,'0'),status:d?.status||'missing',reference:d?.reference||'',justification:d?.justification||''}});
 const unmatched=data.documents.filter(d=>!checklist.some(r=>r.key===d.key)).map(d=>d.key);
 const missing=checklist.filter(r=>r.status==='missing'),review=checklist.filter(r=>r.status==='available'),exceptions=checklist.filter(r=>r.status==='not_applicable');
 const requestDraft='Borrador para el responsable documental: para preparar el expediente de '+(data.product_name.trim()||'[producto pendiente]')+', favor aportar '+(missing.map(r=>r.label).join('; ')||'las aclaraciones y soportes de revisión pendientes')+'. Confirmar versión, fecha, titular y fabricante. No remitir credenciales ni datos de pacientes.';
 return {jurisdiction:'El Salvador',authority:'Superintendencia de Regulación Sanitaria (SRS)',product_name:data.product_name,product_identity:Object.fromEntries(Object.keys(identityFields).map(key=>[key,data[key]||''])),classification:{product_type:data.product_type,origin:data.origin,procedure:data.procedure,manufacturing_contract:data.manufacturing_contract},state:questions.length?'Completar clasificación':'Preparación de expediente; validación profesional y requisitos locales pendientes',questions,checklist,unmatched_documents:unmatched,missing:missing.map(r=>r.key),pending_content_review:review.map(r=>r.key),exceptions_to_validate:exceptions.map(r=>r.key),next_actions:[...questions.map(text=>({priority:'Clasificación',task:text})),...missing.map(r=>({priority:'Recopilación',task:'Solicitar '+r.label})),...review.map(r=>({priority:'Revisión',task:'Verificar contenido, consistencia y vigencia de '+r.label})),...exceptions.map(r=>({priority:'Aplicabilidad',task:'Validar justificación de '+r.label})),{priority:'Control final',task:'Confirmar checklist con guía y formularios vigentes de SRS; firma, presentación y pagos por el responsable autorizado.'}],request_draft:requestDraft,tracking_template:{case_number:null,observations:[],next_deadline:null,note:'Cargar fecha y plazo desde notificación oficial; no se ha presentado solicitud ni activado seguimiento automático.'},sources:SV_REGISTRATION_SOURCES,submitted:false,approved:false,scope:'Prelista orientativa por bloques; no exhaustiva ni certificación de cumplimiento. Los estados y referencias son aportados; no se han leído ni autenticado archivos. No fija aranceles ni plazos de resolución. No se ha accedido al portal de la SRS.'};
}

